Definition retK {R X} (P : mstate -> X -> Prop) (k : mstate -> X -> M R) (t : M R) : Prop :=
  (exists st' x, t = k st' x /\ P st' x) \/ undef t.
Definition retK1 {R} (P : mstate -> Prop) (k : mstate -> M R) (t : M R) : Prop :=
  (exists st', t = k st' /\ P st') \/ undef t.

