  | |- retK1 _ _ (guard ?t ?c ?kk ?b) => destruct (guard_shape t c kk b) as [-> | ?U]; [| right; exact U]
  end.

Ltac shape_case :=
  lazymatch goal with
  | |- retK _ _ (match ?c with _ => _ end) => destruct c
  | |- retK1 _ _ (match ?c with _ => _ end) => destruct c
  end.
